(function(){
'use strict';
const D=window.SelfStudyData,C=window.SelfStudyCore,S=window.SELF_STUDY_SAMPLES,E=C.escapeHTML;
const main=document.getElementById('main'),warning=document.getElementById('storage-warning'),live=document.getElementById('live-status');
let state,storageFailed=false,current=null,readerOpen=window.matchMedia('(min-width: 1040px)').matches,persistTimer;
const read=key=>{try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}};
try{state=C.migrate(read(C.KEY),read(C.LEGACY_KEY),D.questions);persist();}catch{state=C.fresh();showStorageWarning();}
function showStorageWarning(){storageFailed=true;warning.hidden=false;warning.textContent='這個瀏覽器暫時無法儲存答案；目前可以繼續練習，關閉頁面後本次內容可能消失。';}
function persist(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(C.KEY,JSON.stringify(state));if(storageFailed){storageFailed=false;warning.hidden=true;}}catch{showStorageWarning();}}
function announce(text){live.textContent=text;}
function draft(q){return state.questions[q.id]||(state.questions[q.id]=C.draft());}
function route(){const bits=location.hash.slice(1).split('/');if(['practice','lesson'].includes(bits[0]))return{view:'lesson',q:D.questions.find(q=>q.id===bits[1])};if(bits[0]==='article')return{view:'article',p:D.articles.find(p=>p.id===bits[1])};if(bits[0]==='year')return{view:'year',year:Number(bits[1])};return{view:'home'};}
function go(hash){if(location.hash==='#'+hash){render();return;}location.hash=hash;}
function crumb(items){return '<nav class="breadcrumbs" aria-label="所在位置"><a href="#home">年份目錄</a>'+items.map(x=>'<span aria-hidden="true">／</span>'+(x.href?'<a href="'+E(x.href)+'">'+E(x.text)+'</a>':'<span aria-current="page">'+E(x.text)+'</span>')).join('')+'</nav>';}
function articleQuestions(p){return D.questions.filter(q=>q.exerciseId===p.id).sort((a,b)=>a.number-b.number);}
function status(q){const d=state.questions[q.id];return d?.completed?'已完成':d&&(d.type||Object.values(d.answers).some(v=>v.trim()))?'練習中':'未開始';}
function coverage(p){return '第'+articleQuestions(p).map(q=>q.number).join('、')+'題';}
function articleRow(p){const qs=articleQuestions(p),done=qs.filter(q=>state.questions[q.id]?.completed).length;return '<a class="article-row" href="#article/'+p.id+'"><div class="article-index">'+String(D.articles.filter(a=>a.year===p.year).findIndex(a=>a.id===p.id)+1).padStart(2,'0')+'</div><div class="article-info"><h3>'+E(p.title)+'</h3><p>'+E(p.author)+'<span>·</span>'+p.paragraphs.length+'段<span>·</span>'+qs.length+'題</p><small>已收錄'+E(coverage(p))+'</small></div><div class="article-progress"><span>'+done+' / '+qs.length+' 完成</span><span class="arrow" aria-hidden="true">↗</span></div></a>';}
function home(year){const years=year?[year]:[...new Set(D.articles.map(p=>p.year))].sort();const total=D.questions.filter(q=>state.questions[q.id]?.completed).length;return '<div class="directory">'+(year?crumb([{text:year+'年'}]):'')+'<section class="hero"><div><p class="eyebrow">DSE 中文 · 白話文閱讀</p><h1>讀懂這一題，<br>學會下一題。</h1><p class="hero-copy">從辨認題型開始，跟着文本找線索。<br>寫出答案，再練習判斷一份答案值多少分。</p></div><div class="hero-note"><span class="note-label">自主學習路徑</span><ol><li><span>01</span>辨認題型</li><li><span>02</span>找線索・寫答案</li><li><span>03</span>試做評分員</li><li><span>04</span>讀解析・帶走方法</li></ol><p>可以先評示例，之後再回來寫答案。</p></div></section><div class="directory-heading"><h2>'+(year?'選一篇文章':'從年份選擇文章')+'</h2><span>'+D.articles.length+'篇文章 · '+total+' / '+D.questions.length+'題已完成</span></div>'+years.map(y=>'<section class="year-group" aria-labelledby="year-'+y+'"><div class="year-heading"><h2 id="year-'+y+'">'+y+'</h2><span>'+D.articles.filter(p=>p.year===y).length+'篇</span></div><div class="year-articles">'+D.articles.filter(p=>p.year===y).map(articleRow).join('')+'</div></section>').join('')+'<p class="directory-end">選定一篇後，按原題次序逐題練習。完成後再自行選擇下一篇。</p></div>';}
function articlePage(p){const qs=articleQuestions(p),done=qs.filter(q=>state.questions[q.id]?.completed).length;const continueQ=qs.filter(q=>state.questions[q.id]?.lastSeen).sort((a,b)=>(state.questions[b.id]?.lastSeen||'').localeCompare(state.questions[a.id]?.lastSeen||''))[0];const start=continueQ||qs.find(q=>!state.questions[q.id]?.completed)||qs[0];return '<div class="article-page">'+crumb([{href:'#year/'+p.year,text:p.year+'年'},{text:p.title}])+'<header class="article-intro"><div><p class="eyebrow">'+p.year+' · '+E(p.author)+'</p><h1>'+E(p.title)+'</h1><p>'+p.paragraphs.length+'段 · 已收錄'+E(coverage(p))+' · '+done+' / '+qs.length+'題完成</p></div><a class="button primary" href="#lesson/'+start.id+'">'+(continueQ?'繼續第'+start.number+'題':'由第'+start.number+'題開始')+' <span aria-hidden="true">→</span></a></header><section class="question-directory" aria-labelledby="questions-title"><h2 id="questions-title">逐題學習</h2>'+qs.map((q,i)=>'<a class="question-row" href="#lesson/'+q.id+'"><span class="question-number">'+String(i+1).padStart(2,'0')+'</span><div><h3>第'+q.number+'題 <small>'+q.marks+'分</small></h3><p>'+E(q.prompt)+'</p></div><span class="status '+(state.questions[q.id]?.completed?'done':'')+'">'+status(q)+'</span><span aria-hidden="true">→</span></a>').join('')+'</section><details class="article-full"><summary>閱讀全文 <span>'+p.paragraphs.length+'段</span></summary>'+passageText(p)+'</details></div>';}
function passageText(p){return '<div class="passage-text">'+p.paragraphs.map(a=>'<div class="paragraph" id="para-'+a.number+'" data-paragraph="'+a.number+'"><span class="paragraph-number" aria-label="第'+a.number+'段">('+a.number+')</span><p>'+E(a.text)+'</p></div>').join('')+'</div>';}
function questionText(q){return '<section class="question-text" aria-label="原題"><div class="question-title"><h1>第'+q.number+'題</h1><span>'+q.marks+'分</span></div><p class="question-prompt">'+E(q.prompt)+'</p>'+(q.quote?'<blockquote class="question-quote">'+E(q.quote)+'</blockquote>':'')+(q.table?'<div class="table-scroll"><table><thead><tr>'+q.table.headers.map(x=>'<th scope="col">'+E(x)+'</th>').join('')+'</tr></thead><tbody>'+q.table.rows.map(r=>'<tr>'+r.map((x,i)=>i===0?'<th scope="row">'+E(x)+'</th>':'<td>'+E(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>':'')+'</section>';}
function stepper(q,d){const labels=['辨認題型','找線索・作答',q.answerParts.every(p=>p.kind==='choice')?'核對選項':'評分練習','讀解析'];return '<nav class="stepper" aria-label="學習步驟">'+labels.map((x,i)=>'<button type="button" data-action="step" data-step="'+i+'" '+(i>0&&d.type!==q.lesson.type||i===3&&!d.revealed?'disabled':'')+' '+(d.step===i?'aria-current="step"':'')+'><span>'+String(i+1).padStart(2,'0')+'</span><b>'+x+'</b></button>').join('')+'</nav>';}
function classification(q,d){const l=q.lesson,has=d.type===l.type;return '<section class="learning-stage"><p class="stage-label">STEP 01 · 先拆題</p><h2>這一題主要考什麼？</h2><p class="muted">先看題幹要你做的事。作答形式是選擇題，也可以考手法、原因或篇名。</p><div class="type-grid">'+l.choices.map(t=>'<button type="button" class="type-choice '+(d.type===t?'selected':'')+'" data-action="type" data-type="'+t+'" aria-pressed="'+(d.type===t)+'">'+E(D.types[t].label)+'<span aria-hidden="true">'+(d.type===t?'✓':'＋')+'</span></button>').join('')+'</div>'+(d.type?'<div class="type-feedback '+(has?'success':'')+'" role="status"><strong>'+(has?'辨認正確':'再讀一次題幹')+'</strong><p>'+(has?E(l.reason):'留意題目要求你說明的對象和指令。'+E(l.reason))+'</p></div>':'')+'<details class="help-details"><summary>辨型時可留意什麼？</summary><p>先圈「為什麼」「手法」「作用」「以……為題」等指令，再看指定範圍及分題要求。同一道題可以用多種方法；這裏選的是它的主要任務。</p></details>'+(d.type?methodDetails(d.type):'')+'<button class="button primary" type="button" data-action="step" data-step="1" '+(!has?'disabled':'')+'>進入作答 <span aria-hidden="true">→</span></button></section>';}
function methodDetails(type){const t=D.types[type];return '<details class="help-details method-details" data-help="method"><summary>答題步驟與注意事項 <span>點擊展開</span></summary><ol>'+t.steps.map(s=>'<li>'+E(s)+'</li>').join('')+'</ol><p class="tip">'+E(t.note)+'</p></details>';}
function hints(q){return '<details class="help-details question-hints" data-help="specific"><summary>本題提示：找線索與推論 <span>點擊展開</span></summary><p class="muted">先試着想；需要時逐項打開。</p>'+q.lesson.prompts.map((t,i)=>'<details class="hint-level" data-help="hint-'+i+'"><summary>提示 '+(i+1)+'</summary><p>'+E(t)+'</p></details>').join('')+'<div class="locate"><span>到文章中找：</span>'+q.lesson.locate.map(n=>'<button class="paragraph-link" type="button" data-action="locate" data-paragraph="'+n+'">第'+n+'段</button>').join('')+'</div></details>';}
function answerFields(q,d){return q.answerParts.map(p=>'<fieldset class="answer-field"><legend>'+E(p.label)+' <span>'+p.marks+'分</span></legend>'+(p.kind==='choice'?'<div class="choice-list">'+p.choices.map(c=>'<label class="answer-choice"><input type="radio" name="answer-'+p.key+'" data-answer="'+p.key+'" value="'+E(c.value)+'" '+(d.answers[p.key]===c.value?'checked':'')+'><span class="option-letter">'+E(c.value)+'</span><span>'+E(c.text)+'</span></label>').join('')+'</div>':'<label class="sr-only" for="answer-'+p.key+'">'+E(p.label)+'</label><textarea id="answer-'+p.key+'" data-answer="'+p.key+'" rows="'+(p.kind==='short'?2:6)+'" placeholder="'+(p.exactChars?'填寫兩字詞':p.kind==='short'?'寫下簡短答案':'先寫你的理解，並用原文支持。')+'">'+E(d.answers[p.key]||'')+'</textarea><p class="field-note">'+(p.exactChars?'原題要求：兩字詞。':'')+'<span data-count="'+p.key+'">'+Array.from(d.answers[p.key]||'').length+'字</span></p>')+'</fieldset>').join('');}
function answerStage(q,d){const choice=q.answerParts.every(p=>p.kind==='choice');return '<section class="learning-stage"><p class="stage-label">STEP 02 · 由文本出發</p><h2>找到線索，再寫答案</h2>'+methodDetails(q.lesson.type)+hints(q)+'<div class="answer-heading"><h3>你的答案</h3><span class="save-status" id="save-status" role="status">'+(storageFailed?'暫未儲存':'自動儲存')+'</span></div>'+answerFields(q,d)+'<div class="stage-actions"><button class="button primary" type="button" data-action="step" data-step="2">'+(choice?'核對答案與選項':'儲存答案，進入評分')+' <span aria-hidden="true">→</span></button>'+(!choice?'<button class="button text" type="button" data-action="step" data-step="2">先不作答，直接評分</button>':'')+'</div><p class="muted small">'+(choice?'每個選項的理由會在核對後顯示。':'評分模式會加入你已填寫的答案；之後仍可回來重寫。')+'</p></section>';}
function gradeSelect(s,d,i){return '<label class="grade-label" for="grade-'+i+'">你給幾分？ <select id="grade-'+i+'" data-grade="'+s.id+'"><option value="">選擇分數</option>'+Array.from({length:s.outOf+1},(_,n)=>'<option value="'+n+'" '+(d.grades[s.id]===n?'selected':'')+'>'+n+' / '+s.outOf+'分</option>').join('')+'</select></label>';}
function sampleLabel(q,key){const p=q.answerParts.find(p=>p.key===key);const labels={'dse2024-q11':{i:'(i) 感受',ii:'(ii) 用意'},'dse2024-q13':{i:'(i) 手法',ii:'(ii) 效果'},'dse2024-q16':{i:'(i) 事物',ii:'(ii) 寓意'},'dse2025-q20':{i:'(i) 節奏',ii:'(ii) 領悟',iii:'(iii) 引文分析'}};return q.answerParts.length===1?'':labels[q.id]?.[key]||p.label;}
function sampleAnalysis(s){return s.analysis.split(/[−-]/).filter(t=>t.trim()).map(t=>E(t.trim())).join('；').replace(/；；/g,'；');}
function gradingStage(q,d){const choice=q.answerParts.every(p=>p.kind==='choice');if(choice){const results=C.choiceResult(q,d);return '<section class="learning-stage"><p class="stage-label">STEP 03 · 核對選項</p><h2>準備看各項的理由</h2><p>選擇題直接核對答案，每個選項都會解釋。</p>'+q.answerParts.map(p=>'<p class="choice-summary"><strong>'+E(p.label)+'</strong><span>你的選擇：'+(d.answers[p.key]?E(d.answers[p.key]):'尚未選擇')+'</span></p>').join('')+'<button class="button primary" type="button" data-action="reveal">公佈答案，閱讀解析 <span aria-hidden="true">→</span></button><button class="button text" type="button" data-action="step" data-step="1">回去選答案</button></section>';}
 const items=C.gradingItems(q,d,S),ready=C.gradingReady(items,d);return '<section class="learning-stage"><p class="stage-label">STEP 03 · 換個角度看答案</p><h2>你來當評分員</h2><p class="muted">先看內容，替每份答案評分。分數公佈後，再比較理解、例子和推論有何差別。</p>'+(q.id==='dse2025-q20'?'<p class="context-note">(iii) 示例有分析引文，按4分準則評閱。若只重複領悟，還要看(ii)是否已得分。</p>':'')+items.map((s,i)=>'<article class="grading-card"><div class="sample-heading"><h3>示例 '+String(i+1).padStart(2,'0')+'</h3><span>'+E(sampleLabel(q,s.key))+'</span>'+(s.own?'<b class="own-label">你的答案'+(s.merged?' · 已合併':'')+'</b>':'')+'</div><blockquote>'+E(s.text)+'</blockquote>'+gradeSelect(s,d,i)+'</article>').join('')+'<p class="small muted" id="grading-progress">已評 '+items.filter(s=>C.validScore(d.grades[s.id],s.outOf)).length+' / '+items.length+'份</p><button class="button primary" id="reveal-button" type="button" data-action="reveal" '+(!ready?'disabled':'')+'>公佈分數與解析 <span aria-hidden="true">→</span></button><button class="button text" type="button" data-action="step" data-step="1">回去修改答案</button></section>';}
function rubric(q,p){const o=q.official.find(x=>x.key===p.key);return '<details class="rubric-details"><summary>查看'+E(p.label)+'的評分準則</summary>'+(o.bands?.length?'<ul class="bands">'+o.bands.map(b=>'<li><strong>'+b.score+'分</strong><span>'+E(b.text)+'</span></li>').join('')+'</ul>':'')+'<ul>'+(o.criteria||[]).map(t=>'<li>'+E(t)+'</li>').join('')+'</ul></details>';}
function reviewStage(q,d){const items=C.gradingItems(q,d,S),result=C.gradingResult(items,d),choices=C.choiceResult(q,d),l=q.lesson;const choiceOnly=q.answerParts.every(p=>p.kind==='choice');const reviewCards=items.map((s,i)=>'<article class="review-card" id="review-'+s.id+'"><div class="sample-heading"><h3>示例 '+String(i+1).padStart(2,'0')+'</h3><span>'+E(sampleLabel(q,s.key))+'</span>'+(s.own?'<b class="own-label">你的答案</b>':'')+'</div><div class="score-row"><span>你評：<b>'+d.grades[s.id]+' / '+s.outOf+'</b></span>'+(s.score===null?'<span class="score-badge neutral">留作自評</span>':'<span class="score-badge '+(s.score===s.outOf?'full':'')+'">得分 '+s.score+' / '+s.outOf+'</span>')+'</div><blockquote>'+E(s.text)+'</blockquote><div class="analysis"><h4>'+(s.score===null?'怎樣檢查自己的答案':'為什麼是'+s.score+'分？')+'</h4><p>'+sampleAnalysis(s)+'</p>'+(s.score===null?'<p class="small muted">這份自由答案沒有確定分數。對照同分段示例與準則，確認你的自評；填了關鍵詞並不保證得分。</p>':'<p class="comparison-note">'+(s.score===d.grades[s.id]?'你這次評分準確。':'你'+(d.grades[s.id]>s.score?'高估':'低估')+'了'+Math.abs(d.grades[s.id]-s.score)+'分；再對照以上評閱重點。')+'</p>')+'</div><label class="review-check"><input type="checkbox" data-reviewed="'+s.id+'" '+(d.reviewed.includes(s.id)?'checked':'')+'>我明白這份答案的評閱重點</label></article>').join('');
 const choiceCards=q.answerParts.filter(p=>p.kind==='choice').map(p=>{const r=choices.find(x=>x.key===p.key),options=window.COACH_EXAM_COACHING.lessons[q.id].options.filter(o=>o.part===p.key);return '<section class="choice-review"><h3>'+E(p.label)+'</h3><p class="choice-result">你的選擇：'+(r.chosen?E(r.chosen):'未作答')+' <span>正確答案：'+E(r.correct)+' · '+r.score+' / '+r.outOf+'分</span></p>'+p.choices.map(o=>{const detail=options.find(x=>x.value===o.value);return '<article class="option-analysis '+(o.value===p.answer?'correct':'')+'"><div><b>'+E(o.value)+'</b><h4>'+E(o.text)+'</h4><span>'+(o.value===p.answer?'正確':'錯誤')+'</span></div><p>'+E(C.cleanAnalysis(detail?.reason||''))+'</p></article>';}).join('')+'</section>';}).join('');
 return '<section class="learning-stage"><p class="stage-label">STEP 04 · 看懂得分差異</p><h2>'+(choiceOnly?'每個選項，逐一核對':'答案不是越長越高分')+'</h2>'+(!choiceOnly?'<div class="result-banner"><strong>'+result.correct+' / '+result.total+'</strong><span>示例評分判斷準確<br><small>你的自由答案另作準則自評</small></span></div>':'')+'<section class="explanation-overview"><h3>這題的解題關鍵</h3><ol>'+l.review.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol></section>'+choiceCards+reviewCards+q.answerParts.filter(p=>p.kind!=='choice').map(p=>rubric(q,p)).join('')+(!choiceOnly?'<section class="self-check"><h3>用準則回看你的答案</h3>'+q.rubric.map((r,i)=>'<label><input type="checkbox" data-self-check="'+i+'" '+(d.selfChecks.includes(i)?'checked':'')+'><span><strong>'+E(r.label)+'</strong>'+E(r.detail.replace(/來源/g,'').replace(/文件/g,''))+'</span></label>').join('')+'</section>':'')+'<section class="transfer-note"><p class="eyebrow">帶到其他文章</p><h3>記住方法，再換一個情境</h3><ol>'+l.transfer.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol><label for="learning-note">用一句話記下下次會怎樣做 <span>選填</span></label><textarea id="learning-note" data-note rows="2" placeholder="例如：先拆出引文的每個關鍵元素，再逐一找文本支持。">'+E(d.note)+'</textarea></section><div class="stage-actions"><button class="button primary" type="button" data-action="complete">'+(d.completed?'已完成本題 ✓':'完成本題')+'</button><button class="button secondary" type="button" data-action="step" data-step="1">回去重寫答案</button></div><p class="completion-message" id="completion-message" role="status">'+(d.completed?'已記下你的進度，可以繼續同一篇的下一題。':'')+'</p>'+nextAction(q,d)+'</section>';}
function nextAction(q,d){const next=C.nextQuestion(D,q);return '<div class="next-question" id="next-question" '+(!d.completed?'hidden':'')+'>'+(next?'<a class="button primary" href="#lesson/'+next.id+'">同篇下一題：第'+next.number+'題 <span aria-hidden="true">→</span></a>':'<a class="button primary" href="#article/'+q.exerciseId+'">回到本篇，查看學習進度 <span aria-hidden="true">→</span></a>')+'</div>';}
function lessonPage(q){const p=D.articles.find(p=>p.id===q.exerciseId),d=draft(q),qs=articleQuestions(p);if(d.type!==q.lesson.type)d.step=0;if(d.step===3&&!d.revealed)d.step=2;d.lastSeen=new Date().toISOString();persist();const stages=[classification,answerStage,gradingStage,reviewStage];return '<div class="lesson-page">'+crumb([{href:'#year/'+p.year,text:p.year+'年'},{href:'#article/'+p.id,text:p.title},{text:'第'+q.number+'題'}])+'<div class="lesson-heading"><a class="back-link" href="#article/'+p.id+'">← 本篇題目</a><nav class="question-rail" aria-label="同篇題目">'+qs.map(x=>'<a href="#lesson/'+x.id+'" '+(x.id===q.id?'aria-current="page"':'')+' class="'+(state.questions[x.id]?.completed?'done':'')+'" aria-label="第'+x.number+'題'+(state.questions[x.id]?.completed?'，已完成':'')+'">'+x.number+(state.questions[x.id]?.completed?'<span aria-hidden="true">·</span>':'')+'</a>').join('')+'</nav><span class="lesson-count">'+(qs.findIndex(x=>x.id===q.id)+1)+' / '+qs.length+'題</span></div><div class="lesson-layout"><aside class="reader-panel"><details class="reader" id="reader" '+(readerOpen?'open':'')+'><summary><span>閱讀原文 · '+E(p.title)+'</span><small>'+p.paragraphs.length+'段</small></summary><div class="reader-content">'+passageText(p)+'</div></details></aside><div class="coach-panel">'+stepper(q,d)+questionText(q)+stages[d.step](q,d)+'</div></div></div>';}
function render(){clearTimeout(persistTimer);current=route();if(current.view==='lesson'&&!current.q||current.view==='article'&&!current.p||current.view==='year'&&!D.articles.some(p=>p.year===current.year)){main.innerHTML='<div class="empty-page"><h1>找不到這道題目</h1><a class="button primary" href="#home">回到年份目錄</a></div>';return;}document.title=(current.q?'第'+current.q.number+'題 · ':current.p?current.p.title+' · ':'')+'閱讀答題教練';main.innerHTML=current.view==='lesson'?lessonPage(current.q):current.view==='article'?articlePage(current.p):home(current.year);window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
main.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled||current.view!=='lesson')return;const q=current.q,d=draft(q),action=button.dataset.action;
 if(action==='type'){d.type=button.dataset.type;d.completed=false;persist();render();return;}
 if(action==='step'){const n=Number(button.dataset.step);if(n>0&&d.type!==q.lesson.type||n===3&&!d.revealed)return;d.step=n;persist();render();return;}
 if(action==='locate'){const r=document.getElementById('reader');r.open=true;readerOpen=true;const p=main.querySelector('.reader [data-paragraph="'+button.dataset.paragraph+'"]');if(p){main.querySelectorAll('.paragraph.located').forEach(x=>x.classList.remove('located'));p.classList.add('located');p.scrollIntoView({behavior:'smooth',block:'center'});}return;}
 if(action==='reveal'){const items=C.gradingItems(q,d,S);if(items.length&&!C.gradingReady(items,d))return;d.revealed=true;d.step=3;persist();render();announce('分數及每份答案的解析已公佈。');return;}
 if(action==='complete'){const items=C.gradingItems(q,d,S);if(items.some(s=>!d.reviewed.includes(s.id))){announce('請先逐份閱讀示例解析，勾選你已明白的評閱重點。');document.getElementById('completion-message').textContent='請先逐份閱讀示例解析，勾選你已明白的評閱重點。';const s=items.find(s=>!d.reviewed.includes(s.id));document.getElementById('review-'+s.id)?.scrollIntoView({behavior:'smooth',block:'center'});return;}d.completed=true;persist();document.getElementById('completion-message').textContent='已完成本題。把方法帶到同一篇的下一題。';document.getElementById('next-question').hidden=false;button.textContent='已完成本題 ✓';announce('本題已完成。');}
});
main.addEventListener('input',e=>{if(current.view!=='lesson')return;const t=e.target,d=draft(current.q);if(t.dataset.answer!==undefined&&t.tagName==='TEXTAREA'){C.updateAnswer(d,t.dataset.answer,t.value);const count=main.querySelector('[data-count="'+t.dataset.answer+'"]');if(count)count.textContent=Array.from(t.value).length+'字';document.getElementById('save-status').textContent='儲存中…';clearTimeout(persistTimer);persistTimer=setTimeout(()=>{persist();const s=document.getElementById('save-status');if(s)s.textContent=storageFailed?'暫未儲存':'已儲存';},250);}if(t.hasAttribute('data-note')){d.note=t.value;clearTimeout(persistTimer);persistTimer=setTimeout(persist,250);}});
main.addEventListener('change',e=>{if(current.view!=='lesson')return;const t=e.target,q=current.q,d=draft(q);if(t.dataset.answer!==undefined){C.updateAnswer(d,t.dataset.answer,t.value);persist();}if(t.dataset.grade){const v=t.value===''?null:Number(t.value),items=C.gradingItems(q,d,S),s=items.find(x=>x.id===t.dataset.grade);if(s&&C.validScore(v,s.outOf))d.grades[s.id]=v;else delete d.grades[t.dataset.grade];persist();const ready=C.gradingReady(items,d);document.getElementById('reveal-button').disabled=!ready;document.getElementById('grading-progress').textContent='已評 '+items.filter(s=>C.validScore(d.grades[s.id],s.outOf)).length+' / '+items.length+'份';}if(t.dataset.reviewed){d.reviewed=d.reviewed.filter(x=>x!==t.dataset.reviewed);if(t.checked)d.reviewed.push(t.dataset.reviewed);persist();}if(t.dataset.selfCheck!==undefined){const n=Number(t.dataset.selfCheck);d.selfChecks=d.selfChecks.filter(x=>x!==n);if(t.checked)d.selfChecks.push(n);persist();}});
main.addEventListener('toggle',e=>{const t=e.target;if(t.id==='reader')readerOpen=t.open;if(t.classList?.contains('help-details')){const label=t.querySelector(':scope > summary > span');if(label)label.textContent=t.open?'點擊收起':'點擊展開';}if(current.view==='lesson'&&t.dataset.help&&t.open){const d=draft(current.q);if(!d.opened.includes(t.dataset.help)){d.opened.push(t.dataset.help);persist();}}},true);
window.addEventListener('hashchange',()=>{persist();render();});window.addEventListener('pagehide',persist);window.addEventListener('storage',e=>{if(e.key!==C.KEY)return;try{const next=JSON.parse(e.newValue);if(next?.version!==1)return;const id=current.q?.id;for(const [k,v]of Object.entries(next.questions||{}))if(k!==id)state.questions[k]=v;if(id)announce('另一個分頁的進度已更新；這題保留目前分頁的答案。');else render();}catch{}});
render();
})();
